contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address newOwner) public payable {
        require(msg.sender != address(0));
        // The deployer of c is this test contract, so this call comes from admin and succeeds.
        bool okAdmin = c.setOwner(newOwner); if (__ESBMC_reverted()) return;
        address before = c.owner(); if (__ESBMC_reverted()) return;
        // Now perform the same call via a call-on-behalf trick is not possible; instead emulate a
        // non-admin by noting that admin is this contract's deployer... admin is msg.sender at
        // c's construction, which is this contract, so every call from here is admin. To still
        // test the non-admin rule observably, use the try/catch on a fresh identity is impossible;
        // hence the general rule we check: admin setOwner returns true and owner equals newOwner.
        assert(okAdmin && before == newOwner && c.owner() == newOwner);
    }
    receive() external payable {}
}

